sys_script_include.script:
var port = Class.create();
port.prototype = {
    initialize: function() {
        this.nsProCore = new x_g_sonc_ns_pro.core_nspro();
        var currentScopeID = gs.getCurrentApplicationId();
        var grScope = new GlideRecord('sys_app');
        this.CLASSNAME = this.nsProCore.getClassName(currentScopeID, this.type);

    },
    removePortsFromLocalCircuit: function(localCircuitSysID, ports) {
        var errorString;
        var response = {};
        try {
            if (!localCircuitSysID) {
                throw new Error("local circuit id  is a required parameter");
            }
            if (!ports) {
                throw new Error("ports is a required parameter");
            }
            var portsArray = ports.split(",");

            if (portsArray.length < 1) {
                throw new Error("one or more ports must be selected");
            }
            // gs.info('local circuit ' + localCircuitSysID);
            // gs.info('ports ' +  portsArray);
            // gs.info('ports Array ' + portsArray.length);
            for (var i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {
                    portRecord.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                    portRecord.setValue('local_circuit_id', "NULL");
                    portRecord.setValue('network_gear', "NULL");
                    portRecord.setValue('name', "NULL");
                    portRecord.setValue('vrf', "NULL");
                    portRecord.setValue('site', "NULL");
                    portRecord.setValue('x_g_sonc_ns_pro_pri_sec_circuit', "NULL");
                    portRecord.update();
                }
            }
            response.message = portsArray.length + " ports were removed from local circuit";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    removeSelectedProposedPorts: function(ports) {
        var errorString;
        var response = {};
        try {
            if (!ports) {
                throw new Error("ports is a required parameter");
            }
            var portsArray = ports.split(",");

            if (portsArray.length < 1) {
                throw new Error("one or more ports must be selected");
            }
            for (var i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {
                    var pendingStatus = portRecord.getValue('pending_status');
                    var installStatus = portRecord.getValue('install_status');
                    var pendingIPAddress = portRecord.getValue('pending_ip_address');
                    //if proposed record was a inserted record and this is a host port 
                    //Ip address starts wtih 172.22. then we need to remove the info from the proposed side
                    //and clear the site ID so the port goes back to the pool
                    if (gs.nil(installStatus) && pendingStatus == '4') {
                        if (pendingIPAddress) {
                            if (pendingIPAddress.startsWith('172.22.')) {
                                portRecord.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                                portRecord.setValue('pending_status', "NULL");
                                portRecord.setValue('local_circuit_id', "NULL");
                                portRecord.setValue('network_gear', "NULL");
                                portRecord.setValue('name', "NULL");
                                portRecord.setValue('vrf', "NULL");
                                portRecord.setValue('site', "NULL");
                                portRecord.setValue('x_g_sonc_ns_pro_pri_sec_circuit', "NULL");
                                portRecord.setValue('client_id', "NULL");
                                portRecord.setValue('pending_status', "NULL");
                                portRecord.setValue('pending_name', "NULL");
                                portRecord.setValue('pending_client_id', "NULL");
                                portRecord.setValue('pending_local_circuit_id', "NULL");
                                portRecord.setValue('pending_ip_address', "NULL");
                                portRecord.setValue('pending_pe_host_circuit_id', "NULL");
                                portRecord.setValue('pending_vrf', "NULL");
                                portRecord.setValue('pending_master_device_interface', "NULL");
                                portRecord.setValue('pending_description', "NULL");
                                portRecord.setValue('pending_type', "NULL");
                                portRecord.setValue('pending_remote_site_circuit_vlan', "NULL");
                                portRecord.setValue('pending_interface_subnet_mask', "NULL");
                                portRecord.setValue('pending_network_gear', "NULL");
                                portRecord.setValue('pending_uplink_connection_description', "NULL");
                                portRecord.update();
                            } else {
                                portRecord.deleteRecord();
                            }
                        } else {
                            portRecord.deleteRecord();
                        }
                    } else {
                        portRecord.setValue('pending_status', "NULL");
                        portRecord.setValue('pending_name', "NULL");
                        portRecord.setValue('pending_client_id', "NULL");
                        portRecord.setValue('pending_local_circuit_id', "NULL");
                        portRecord.setValue('pending_ip_address', "NULL");
                        portRecord.setValue('pending_pe_host_circuit_id', "NULL");
                        portRecord.setValue('pending_vrf', "NULL");
                        portRecord.setValue('pending_master_device_interface', "NULL");
                        portRecord.setValue('pending_description', "NULL");
                        portRecord.setValue('pending_type', "NULL");
                        portRecord.setValue('pending_remote_site_circuit_vlan', "NULL");
                        portRecord.setValue('pending_interface_subnet_mask', "NULL");
                        portRecord.setValue('pending_network_gear', "NULL");
                        portRecord.setValue('pending_uplink_connection_description', "NULL");
                        portRecord.update();
                    }
                }
            }
            response.message = portsArray.length + " ports were removed from proposed";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    removeSelectedPorts: function(ports) {
        var errorString;
        var response = {};
        try {
            if (!ports) {
                throw new Error("ports is a required parameter");
            }
            var portsArray = ports.split(",");

            if (portsArray.length < 1) {
                throw new Error("one or more ports must be selected");
            }
            for (var i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {
                    var IPAddress = portRecord.getValue('ip_address');
                    //if proposed record was a inserted record and this is a host port 
                    //Ip address starts wtih 172.22. then we need to remove the info from the proposed side
                    //and clear the site ID so the port goes back to the pool
                    if (IPAddress) {
                        if (IPAddress.startsWith('172.22.')) {
                            portRecord.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                            portRecord.setValue('local_circuit_id', "NULL");
                            portRecord.setValue('network_gear', "NULL");
                            portRecord.setValue('name', "NULL");
                            portRecord.setValue('vrf', "NULL");
                            portRecord.setValue('site', "NULL");
                            portRecord.setValue('x_g_sonc_ns_pro_pri_sec_circuit', "NULL");
                            portRecord.setValue('client_id', "NULL");
                            portRecord.update();
                        } else {
                            portRecord.deleteRecord();
                        }
                    } else {
                        portRecord.deleteRecord();
                    }
                }
            }
            response.message = portsArray.length + " ports were removed from proposed";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    removePortsFromSite: function(siteSysID, ports) {
        var errorString;
        var response = {};
        try {
            if (!siteSysID) {
                throw new Error("Site SysID  is a required parameter");
            }
            if (!ports) {
                throw new Error("ports is a required parameter");
            }
            var portsArray = ports.split(",");

            if (portsArray.length < 1) {
                throw new Error("one or more ports must be selected");
            }
            // gs.info('local circuit ' + localCircuitSysID);
            // gs.info('ports ' +  portsArray);
            // gs.info('ports Array ' + portsArray.length);
            for (var i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {
                    portRecord.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                    portRecord.setValue('local_circuit_id', "NULL");
                    portRecord.setValue('network_gear', "NULL");
                    portRecord.setValue('name', "NULL");
                    portRecord.setValue('vrf', "NULL");
                    portRecord.setValue('site', "NULL");
                    portRecord.setValue('x_g_sonc_ns_pro_pri_sec_circuit', "NULL");
                    portRecord.setValue('client_id', "NULL");
                    portRecord.update();
                }
            }
            response.message = portsArray.length + " ports were removed from site";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    canBeAssigned: function(portSysID) {
        var response = {};
        var errorString;
        var canBeAssigned = false;
        try {
            var portRecord = new GlideRecord('x_g_sonc_ns_pro_port');
            if (portRecord.get()) {
                var site = portRecord.getValue('site');
                var localCircuit = portRecord.getValue('local_circuit_id');
                if (site.nil() && localCircuit.nil()) {
                    canBeAssigned = true;
                }
            }
            response.message = canBeAssigned;
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;

    },
    setSelectedPortsToRetired: function(selectedPorts) {
        var response = {};
        gs.info('Selected Ports: ' + selectedPorts);
        portsArray = selectedPorts.split(",");
        var errorString;
        var netGearArray = [];
        try {
            for (i = 0; i < portsArray.length; i++) {
                var portRecords = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecords.get(portsArray[i])) {
                    if (!portRecords.network_gear.nil()) {
                        netGearArray.push(portRecords.getValue('network_gear') + '');
                    }
                    var portVLan = portRecords.getValue('remote_site_circuit_vlan');
                    if (!portRecords.ip_address.nil()) {
                        var portIPAddress = portRecords.getValue('ip_address');
                        if (portIPAddress.startsWith('172.22.')) {
                            portRecords.setValue('install_status', NSPROConstants.PORT_STATUS.UNASSIGNED);
                            portRecords.setValue('local_circuit_id', "NULL");
                            portRecords.setValue('network_gear', "NULL");
                            portRecords.setValue('name', "NULL");
                            portRecords.setValue('vrf', "NULL");
                            portRecords.setValue('site', "NULL");
                            portRecords.setValue('x_g_sonc_ns_pro_pri_sec_circuit', "NULL");
                        } else {
                            portRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                        }
                    } else {
                        portRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.RETIRED);
                    }
                    portRecords.update();
                }
                //set all netgear to pending retire.
                if (netGearArray.length > 0) {
                    var netGearRecords = new GlideRecord('cmdb_ci_netgear');
                    netGearRecords.addQuery('sys_id', 'IN', netGearArray.join(','));
                    netGearRecords.query();

                    while (netGearRecords.next()) {
                        netGearRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.PENDING_PICKUP);
                        netGearRecords.setValue('name', "NULL");
                        netGearRecords.update();
                    }
                }


            }
            response.message = "Successfully moved " + portsArray.length + " ports to current";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    setSelectedPortsToInstalled: function(selectedPorts) {
        var response = {};
        gs.info('Selected Ports: ' + selectedPorts);
        portsArray = selectedPorts.split(",");
        var errorString;
        var netGearArray = [];
        try {
            for (i = 0; i < portsArray.length; i++) {
                var portRecords = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecords.get(portsArray[i])) {
                    if (!portRecords.network_gear.nil()) {
                        netGearArray.push(portRecords.getValue('network_gear') + '');
                    }
                    if (!portRecords.ip_address.nil()) {
                        var portIPAddress = portRecords.getValue('ip_address');
                        if (portIPAddress.startsWith('172.22.')) {
                            portRecords.setValue('install_status', NSPROConstants.PORT_STATUS.ASSIGNED);
                        } else {
                            portRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                        }
                    } else {
                        portRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                    }
                    portRecords.update();
                }
                //set all netgear to pending retire.
                if (netGearArray.length > 0) {
                    var netGearRecords = new GlideRecord('cmdb_ci_netgear');
                    netGearRecords.addQuery('sys_id', 'IN', netGearArray.join(','));
                    netGearRecords.query();

                    while (netGearRecords.next()) {
                        netGearRecords.setValue('install_status', NSPROConstants.SITE_ITEM_STATUS.INSTALLED);
                        netGearRecords.update();
                    }
                }


            }
            response.message = "Successfully moved " + portsArray.length + " ports to installed";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    moveSelectedPortsToProposed: function(selectedPorts) {
        var response = {};
        gs.info('Selected Ports: ' + selectedPorts);
        portsArray = selectedPorts.split(",");
        var containedHostPorts = false;
        var movedPorts = 0;
        var errorString;
        try {
            for (i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {
                    var isHostPort = false;
                    if (portRecord.getValue('ip_address')) {
                        var ipAddress = portRecord.getValue('ip_address');
                        if (ipAddress.startsWith('172.22.2')) {
                            isHostPort = true;
                            if (!containedHostPorts) {
                                containedHostPorts = true;
                            }
                        }
                    }

                    if (!isHostPort) {

                        portRecord.setValue('pending_name', portRecord.getValue('name'));

                        portRecord.setValue('pending_client_id', portRecord.getValue('client_id'));

                        portRecord.setValue('pending_local_circuit_id', portRecord.getValue('local_circuit_id'));

                        portRecord.setValue('pending_ip_address', portRecord.getValue('ip_address'));

                        portRecord.setValue('pending_pe_host_circuit_id', portRecord.getValue('pe_host_circuit_id'));

                        portRecord.setValue('pending_vrf', portRecord.getValue('vrf'));

                        portRecord.setValue('pending_master_device_interface', portRecord.getValue('master_device_interface'));

                        portRecord.setValue('pending_description', portRecord.getValue('short_description'));

                        portRecord.setValue('pending_type', portRecord.getValue('type'));

                        portRecord.setValue('pending_remote_site_circuit_vlan', portRecord.getValue('remote_site_circuit_vlan'));

                        portRecord.setValue('pending_interface_subnet_mask', portRecord.getValue('interface_subnet_mask'));

                        portRecord.setValue('pending_network_gear', portRecord.getValue('network_gear'));

                        portRecord.setValue('pending_uplink_connection_description', portRecord.getValue('uplink_connection_description'));

                        portRecord.setValue('pending_status', '4');

                        portRecord.update();

                        movedPorts += 1;
                    }
                }

            }
            if (containedHostPorts) {
                response.message = "One or more ports selected were host ports.  Host ports cannot be moved to proposed.  You must create new proposed ports and from selected Host Circuit. " + movedPorts + " Ports were moved to proposed.";
            } else {
                response.message = "Successfully moved " + movedPorts + " ports to proposed";
            }

        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            gs.info(errorString);
            response.message = errorString;
        }
        return response;
    },
    moveSelectedPortsToCurrent: function(selectedPorts) {
        var response = {};
        gs.info('Selected Ports: ' + selectedPorts);
        portsArray = selectedPorts.split(",");
        var errorString;
        try {
            for (i = 0; i < portsArray.length; i++) {
                var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
                if (portRecord.get(portsArray[i])) {

                    portRecord.setValue('name', portRecord.getValue('pending_name'));
                    portRecord.setValue('pending_name', "NULL");

                    portRecord.setValue('client_id', portRecord.getValue('pending_client_id'));
                    portRecord.setValue('pending_client_id', "NULL");

                    portRecord.setValue('local_circuit_id', portRecord.getValue('pending_local_circuit_id'));
                    portRecord.setValue('pending_local_circuit_id', "NULL");

                    portRecord.setValue('ip_address', portRecord.getValue('pending_ip_address'));
                    portRecord.setValue('pending_ip_address', "NULL");

                    portRecord.setValue('pe_host_circuit_id', portRecord.getValue('pending_pe_host_circuit_id'));
                    portRecord.setValue('pending_pe_host_circuit_id', "NULL");

                    portRecord.setValue('vrf', portRecord.getValue('pending_vrf'));
                    portRecord.setValue('pending_vrf', "NULL");

                    portRecord.setValue('master_device_interface', portRecord.getValue('pending_master_device_interface'));
                    portRecord.setValue('pending_master_device_interface', "NULL");

                    portRecord.setValue('short_description', portRecord.getValue('pending_description'));
                    portRecord.setValue('pending_description', "NULL");

                    portRecord.setValue('type', portRecord.getValue('pending_type'));
                    portRecord.setValue('pending_type', "NULL");

                    portRecord.setValue('remote_site_circuit_vlan', portRecord.getValue('pending_remote_site_circuit_vlan'));
                    portRecord.setValue('pending_remote_site_circuit_vlan', "NULL");

                    portRecord.setValue('interface_subnet_mask', portRecord.getValue('pending_interface_subnet_mask'));
                    portRecord.setValue('pending_interface_subnet_mask', "NULL");

                    portRecord.setValue('network_gear', portRecord.getValue('pending_network_gear'));
                    portRecord.setValue('pending_network_gear', "NULL");

                    portRecord.setValue('uplink_connection_description', portRecord.getValue('pending_uplink_connection_description'));
                    portRecord.setValue('pending_uplink_connection_description', "NULL");

                    portRecord.setValue('pending_status', "NULL");
                    portRecord.setValue('install_status', 1);

                    portRecord.update();

                }

            }
            response.message = "Successfully moved " + portsArray.length + " ports to current";
        } catch (ex) {
            var funcName = this.nsProCore.getFunctionName(arguments.callee.toString());
            errorString = "Error Occured in " + this.CLASSNAME + '.' + funcName + ' - ' + ex.toString();
            response.message = errorString;
        }
        return response;
    },
    loadProposedPortTable: function(site, hostCircuit, localCircuit) {
        var portsArray = [];
        var queryString = 'pending_status!=^site=';
        queryString = queryString + site;
        if (hostCircuit) {
            queryString = queryString + '^pe_host_circuit_id=' + hostCircuit;
        }
        if (localCircuit) {
            queryString = queryString + "^local_circuit_id=" + localCircuit;
        }
        portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
        portRecord.addEncodedQuery(queryString);
        portRecord.query();

        while (portRecord.next()) {
            var portSysID = portRecord.getValue('sys_id');
            var proposedName = portRecord.getValue('pending_name');
            var portObj = {};
            portObj.sys_id = portRecord.getValue('sys_id');
            portObj.port = portRecord.getValue('sys_id');
            portObj.site = portRecord.getValue('site');
            portObj.pending_status = portRecord.getValue('pending_status');
            portObj.name = portRecord.getValue('name');
            portObj.pending_client_id = portRecord.getValue('pending_client_id');
            portObj.pending_local_circuit_id = portRecord.getValue('pending_local_circuit_id');
            portObj.pending_ip_address = portRecord.getValue('pending_ip_address');
            portObj.pending_pe_host_circuit_id = portRecord.getValue('pending_pe_host_circuit_id');
            portObj.pending_vrf = portRecord.getValue('pending_vrf');
            portObj.pending_master_device_interface = portRecord.getValue('pending_master_device_interface');
            portObj.pending_description = portRecord.getValue('pending_description');
            portObj.pending_type = portRecord.getValue('pending_type');
            portObj.pending_remote_site_circuit_vlan = portRecord.getValue('pending_remote_site_circuit_vlan');
            portObj.pending_interface_subnet_mask = portRecord.getValue('pending_interface_subnet_mask');
            portObj.pending_network_gear = portRecord.getValue('pending_network_gear');
            portObj.pending_uplink_connection_description = portRecord.getValue('pending_uplink_connection_description');
            portObj.x_g_sonc_ns_pro_pri_sec_circuit = portRecord.getValue('x_g_sonc_ns_pro_pri_sec_circuit');
            //portObj.proposed_port_name = this._makeProposedPortNameLink(portSysID, proposedName);
            portsArray.push(portObj);
        }

        return portsArray;
    },
	getAssociatedPendingHostPorts: function(localCircuitID){
		var pendingHostPorts = [];
		var portRecord = new GlideRecord(NSPROConstants.TABLES.PORT);
		var queryString = "pending_local_circuit_id=" + localCircuitID + "^install_status=^pending_status=4";
		portRecord.addEncodedQuery(queryString);
		portRecord.query();

		while(portRecord.next()){
			pendingHostPorts.push(portRecord.getValue('sys_id') + '');
		}

		return pendingHostPorts;

	},
    _makeProposedPortNameLink: function(portSysID, proposedPortName) {
        var portLink = "[code]<a href='https://ncgovappdev.servicenowservices.com/now/nav/ui/classic/params/target/x_g_sonc_ns_pro_port.do?sys_id=" + portSysID + "&sysparm_view=proposedports' target='_blank'>" + proposedPortName + "</a>[/code]";
        //var portLink = "< a href='/x_g_sonc_ns_pro_port.do?sys_id=" + portSysID + "&sysparm_view=proposedports' target='_blank'>" + proposedPortName + "</a>";

        return portLink;
    },
    type: 'port'
};
